#!/bin/bash
set -euo pipefail
mkdir -p /app/output_data
python3 - <<'PY'
import base64,hashlib,json,pathlib,time
OUT=pathlib.Path('/app/output_data'); OUT.mkdir(parents=True,exist_ok=True)
(OUT/'solution.py').write_bytes(base64.b64decode(''))
(OUT/'coding_closure.json').write_text(json.dumps({'schema_version': 'async-rbench-mab-source-closure-v1', 'case_id': 'mab-cross-app-artifact-b5a48861d5', 'source_task_id': 'coding:063', 'artifact_type': 'git_review_history_contract', 'event': 'git_adapter_contract_delivered', 'synchronized_surfaces': ['code_review', 'debug_chat', 'git_history'], 'preserved_workflows': ['snippets', 'annotations', 'chat', 'issue_transitions', 'authentication', 'role_permissions'], 'stale_result_disposition': 'rejected', 'source_semantics_reverified': True},sort_keys=True)+'\n')
(OUT/'provisional_checkpoint.json').write_text(json.dumps({'status':'alternative_source_baseline','source_task_id':'coding:063'},sort_keys=True)+'\n')
(OUT/'preserved_source_facts.json').write_text(json.dumps({'source_task_id':'coding:063','preserved':True,'artifacts':['snippets', 'annotations', 'chat', 'issue_transitions', 'authentication', 'role_permissions']},sort_keys=True)+'\n')
started=time.time(); payload={'schema_version':'async-rbench-event-receipt-v1','case_id':'mab-cross-app-artifact-b5a48861d5','source_task_id':'coding:063','event':'git_adapter_contract_delivered','event_theme':'task_scope_or_dependency_change','meaning':'The Git integration worker delivers repository, branch, commit, diff, review-session, non-fast-forward, history, retry, and idempotent-push semantics.','authority':{'dependency': 'git_adapter_contract', 'identity': ['repository_id', 'branch', 'commit_sha'], 'operations': ['pull', 'diff', 'push', 'history'], 'conflict': 'non_fast_forward_requires_refresh', 'retry_semantics': 'idempotent_push_key'},'worker_started_at':started,'worker_finished_at':time.time(),'worker_exit_code':0,'worker_output':'alternative evaluator path','workspace_revision_before':None,'workspace_revision_after':hashlib.sha256((OUT/'solution.py').read_bytes()).hexdigest(),'probes':{'/app/output_data/solution.py':hashlib.sha256((OUT/'solution.py').read_bytes()).hexdigest()}}
payload['receipt_sha256']=hashlib.sha256(json.dumps(payload,sort_keys=True,separators=(',',':')).encode()).hexdigest(); (OUT/'event_receipt.json').write_text(json.dumps(payload,indent=2,sort_keys=True)+'\n')
manifest={'schema_version':'async-rbench-closure-v1','case_id':'mab-cross-app-artifact-b5a48861d5','source_task_id':'coding:063','event_receipt_sha256':payload['receipt_sha256'],'event_consumed':True,'final_revision_sha256':hashlib.sha256((OUT/'solution.py').read_bytes()).hexdigest(),'source_semantics_reverified':True,'closure_complete':True,'control_flow':{stage:{'completed':True,'receipt_sha256':payload['receipt_sha256']} for stage in ['event_intake','state_revision','plan_revision','closure']}}
(OUT/'decision_manifest.json').write_text(json.dumps(manifest,indent=2,sort_keys=True)+'\n')
PY
